#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

#define MAXN 100005

ll node_val[MAXN];
ll max_profit = 0;

struct Edge {
    int to;
    int w;
    struct Edge* next;
};

struct Edge* adj[MAXN];

void add_edge(int u, int v, int w) {
    struct Edge* e = (struct Edge*)malloc(sizeof(struct Edge));
    e->to = v;
    e->w = w;
    e->next = adj[u];
    adj[u] = e;
}

ll dfs(int u, int parent) {
    ll sum = node_val[u];

    for (struct Edge* e = adj[u]; e != NULL; e = e->next) {
        int v = e->to;
        if (v == parent) continue;

        ll sub = dfs(v, u);
        if (sub - e->w > max_profit) {
            max_profit = sub - e->w;
        }
        sum += sub;
    }

    return sum;
}

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        adj[i] = NULL;
        node_val[i] = 0;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
